namespace PetTracker.App;

public static class HelpText
{
    private static readonly Dictionary<string,string[]> Texts=new()
    {
        ["autoHeight"]=["Kart sayısına göre otomatik boyutlanır.","Automatically fits the number of cards.","Passt sich automatisch der Kartenzahl an.","Размер автоматически следует числу карточек.","Se ajusta automáticamente al número de tarjetas.","S’adapte automatiquement au nombre de cartes.","Ajusta-se automaticamente ao número de cartões.","يتغير الحجم تلقائياً حسب عدد البطاقات.","कार्ड की संख्या के अनुसार आकार अपने आप बदलता है।","自动适应卡片数量。"],
        ["farmTitle"]=["Farmlanabilir petler","Farmable pets","Farmbare Pets","Питомцы для фарма","Mascotas farmeables","Pets à farmer","Pets para farmar","حيوانات قابلة للتجميع","फ़ार्म किए जा सकने वाले पेट","可刷取宠物"],
        ["farm"]=["Pet Atlası’nda Farmlanabilir petler kategorisini seç. Bölge filtresiyle o haritadaki petleri gör. Tüm Farmlanabilir Petleri Göster seçeneği, seçili haritadaki bütün farm noktalarını birlikte gösterir. Noktalar kayıtlı konumlardır; canlı spawn garantisi değildir. Tür menüsünden Cogni, Fera, Natura, Varian veya Special seç. Pet kartındaki yeşil + peti Tracker'a ekler. Tracker'daki Petler tiki yalnızca görünür tracker petlerini ve eşleşen harita noktalarını gösterir; kırmızı bildirim bu filtrenin açık olduğunu belirtir.","Choose Farmable pets in Pet Atlas, then filter by region. Show all farmable locations displays every recorded farming point on the selected map together. These are recorded locations, not a guarantee of a live spawn. Filter by Cogni, Fera, Natura, Varian or Special. The green + on a pet card adds it to the tracker. Tracker pets only limits pets and map markers to visible tracker cards and the other active filters; a red label indicates this mode.","Im Pet Atlas Farmbare Pets und eine Region wählen. Alle Farm-Orte anzeigen blendet sämtliche gespeicherten Farm-Punkte der gewählten Karte ein. Gespeicherte Orte garantieren keinen aktuellen Spawn. Nach Cogni, Fera, Natura, Varian oder Special filtern. Das grüne + fügt ein Pet zum Tracker hinzu. Nur Tracker-Pets begrenzt Liste und Karte auf sichtbare Tracker-Karten und aktive Filter; ein roter Hinweis kennzeichnet den Modus.","В Атласе выберите питомцев для фарма и регион. «Все места фарма» показывает вместе все записанные точки выбранной карты. Это сохранённые места, а не гарантия живого спавна. Фильтруйте по Cogni, Fera, Natura, Varian или Special. Зелёный + добавляет питомца в трекер. Режим питомцев трекера ограничивает список и карту видимыми карточками и текущими фильтрами; его обозначает красная надпись.","Elige Mascotas farmeables y una región en el Atlas. Mostrar todas las ubicaciones reúne los puntos registrados del mapa elegido. No garantiza que haya un enemigo vivo. Filtra por Cogni, Fera, Natura, Varian o Special. El + verde añade el pet al tracker. Solo pets del tracker limita lista y mapa a tarjetas visibles y filtros activos; una etiqueta roja indica el modo.","Choisissez les pets à farmer et une région dans l’Atlas. Afficher tous les lieux réunit les points enregistrés de la carte sélectionnée. Ces lieux ne garantissent pas une apparition en direct. Filtrez par Cogni, Fera, Natura, Varian ou Special. Le + vert ajoute le pet au tracker. Le mode tracker limite la liste et la carte aux cartes visibles et aux filtres actifs ; une indication rouge signale ce mode.","Escolha pets para farmar e uma região no Atlas. Mostrar todos os locais reúne os pontos registrados no mapa selecionado. Os locais não garantem um spawn ativo. Filtre por Cogni, Fera, Natura, Varian ou Special. O + verde adiciona o pet ao tracker. Só pets do tracker limita lista e mapa aos cartões visíveis e filtros ativos; uma indicação vermelha identifica o modo.","اختر الحيوانات القابلة للتجميع ثم المنطقة في الأطلس. إظهار جميع المواقع يعرض النقاط المسجلة على الخريطة المختارة معاً. المواقع لا تضمن وجود عدو حي. رشّح حسب Cogni أو Fera أو Natura أو Varian أو Special. تضيف علامة + الخضراء الحيوان إلى المتتبع. يقتصر وضع حيوانات المتتبع على البطاقات الظاهرة والمرشحات النشطة، وتوضحه رسالة حمراء.","एटलस में फ़ार्म योग्य पेट और क्षेत्र चुनें। सभी फ़ार्म स्थान विकल्प चुने मानचित्र के दर्ज स्थान एक साथ दिखाता है। ये लाइव स्पॉन की गारंटी नहीं हैं। Cogni, Fera, Natura, Varian या Special चुनें। हरा + पेट को ट्रैकर में जोड़ता है। केवल ट्रैकर मोड सूची और मानचित्र को दिखाई देने वाले कार्ड और सक्रिय फ़िल्टर तक सीमित करता है; लाल संदेश इस मोड को दर्शाता है।","在图鉴中选择可刷取宠物，再筛选地区。显示全部刷取位置会同时显示当前地图的所有已记录地点。这些地点不保证当前有怪物。 可按Cogni、Fera、Natura、Varian或Special筛选。宠物卡片的绿色+将其加入追踪器。仅追踪器宠物模式结合当前筛选条件，仅显示追踪器可见卡片及其地图标记，并以红色提示标明。"],
        ["regionsTitle"]=["Bölge ve elde etme bilgileri","Regions and acquisition","Regionen und Bezugsquellen","Регионы и получение","Regiones y obtención","Régions et obtention","Regiões e obtenção","المناطق وطرق الحصول","क्षेत्र और प्राप्ति","地区与获取方式"],
        ["regions"]=["Bir pete tıklayarak bilgi kartını aç: görseli, ilerlemesi ve wiki’deki elde etme kaynakları burada. Birden fazla haritada bulunan petlerde Haritada göster menüsünden bölge seç. Konumu olmayan petler kategorisi yalnızca kayıtlı harita noktası bulunmayan petleri gösterir.","Click a pet for its portrait, progress and wiki acquisition sources. For pets found on multiple maps, choose a region in Show on map. The No locations category lists pets without recorded map points; their cards may still explain how to obtain them.","Ein Pet anklicken: Porträt, Fortschritt und Wiki-Bezugsquellen. Bei mehreren Karten die Region unter Auf Karte zeigen wählen. Ohne Orte zeigt Pets ohne gespeicherte Kartenpunkte; ihre Karten können Bezugsquellen enthalten.","Нажмите питомца: портрет, прогресс и источники из вики. Для нескольких карт выберите регион в «На карте». Категория без мест содержит питомцев без записанных точек, но в карточке могут быть способы получения.","Pulsa una mascota para ver retrato, progreso y fuentes de la wiki. Si aparece en varios mapas, elige región en Mostrar en mapa. Sin ubicaciones agrupa mascotas sin puntos registrados; su ficha puede indicar cómo conseguirlas.","Cliquez sur un pet pour son portrait, sa progression et ses sources wiki. Pour plusieurs cartes, choisissez la région dans Afficher sur la carte. Sans lieu regroupe les pets sans point enregistré ; leur fiche peut expliquer comment les obtenir.","Clique num pet para retrato, progresso e fontes da wiki. Com vários mapas, escolha a região em Mostrar no mapa. Sem locais lista pets sem pontos registrados; a ficha pode explicar como obtê-los.","اضغط الحيوان لصورته وتقدمه ومصادر الحصول من الويكي. اختر المنطقة من العرض على الخريطة عند تعدد الخرائط. فئة بلا مواقع تضم الحيوانات بلا نقاط مسجلة؛ قد توضح البطاقة طرق الحصول.","पेट दबाकर चित्र, प्रगति और विकी प्राप्ति स्रोत देखें। कई मानचित्र हों तो मानचित्र पर दिखाएँ से क्षेत्र चुनें। बिना स्थान श्रेणी में दर्ज बिंदु रहित पेट हैं; कार्ड में प्राप्ति विधि मिल सकती है।","点击宠物查看头像、进度和维基获取来源。分布在多张地图时，在地图显示菜单中选择地区。无位置分类列出没有已记录坐标的宠物，信息卡仍可能提供获取方式。"],
        ["portraitsHelpTitle"]=["Haritayı kendine göre ayarla","Make the map yours","Karte anpassen","Настройте карту","Personaliza el mapa","Personnalisez la carte","Personalize o mapa","خصص الخريطة","मानचित्र अनुकूलित करें","自定义地图"],
        ["portraitsHelp"]=["Haritada Portre Olarak Göster açıkken noktalar yuvarlak pet resimleri olur; kapalıyken siyah çerçeveli kırmızı noktalar görünür. Fare tekerleğiyle yakınlaştır, sürükleyerek gez. Konumlara odaklan düğmesi noktaları tekrar ekrana sığdırır.","Show Portraits on Map switches between round pet portraits and red dots with black outlines. Zoom with the mouse wheel and drag to pan. Focus locations fits the recorded points back into view.","Porträts auf Karte anzeigen wechselt zwischen runden Bildern und rot-schwarzen Punkten. Mausrad zum Zoomen, Ziehen zum Verschieben. Orte fokussieren passt die Punkte wieder ins Bild.","Портреты на карте переключает круглые изображения и красные точки с чёрной обводкой. Колесо — масштаб, перетаскивание — движение. Фокус мест возвращает точки в кадр.","Mostrar retratos alterna imágenes redondas y puntos rojos con borde negro. Acerca con la rueda y arrastra para moverte. Enfocar ubicaciones vuelve a encuadrar los puntos.","Les portraits alternent avec les points rouges cerclés de noir. Zoomez à la molette et déplacez par glissement. Centrer les lieux remet les points dans le cadre.","Mostrar retratos alterna imagens redondas e pontos vermelhos com contorno preto. Use a roda para zoom e arraste para mover. Focar locais enquadra os pontos novamente.","عرض الصور يبدل بين صور دائرية ونقاط حمراء بإطار أسود. كبّر بعجلة الفأرة واسحب للتحريك. التركيز على المواقع يعيد النقاط إلى العرض.","चित्र विकल्प गोल पेट चित्र और काले किनारे वाले लाल बिंदु बदलता है। पहिए से ज़ूम और खींचकर मानचित्र चलाएँ। स्थानों पर ध्यान बटन बिंदु फिर से स्क्रीन में लाता है।","显示地图头像可在圆形宠物头像和黑边红点之间切换。滚轮缩放，拖动平移。聚焦位置可让已记录地点重新适应视图。"],
        ["setupHandbook"]=["Uygulama rehberi için tıkla","Click to open the app handbook","App-Anleitung öffnen","Открыть руководство","Abrir guía de la aplicación","Ouvrir le guide de l’application","Abrir guia do aplicativo","اضغط لفتح دليل التطبيق","ऐप गाइड खोलने के लिए दबाएँ","点击打开应用指南"],
        ["handbookIntro"]=["Pet Atlası’nın sağ üstündeki kitap ikonuna bas. Fotoğraflı, sekiz sayfalık rehber ayrı bir pencerede açılır; taşıyabilir ve kapatabilirsin.","Click the book icon at the top right of Pet Atlas. A eight-page screenshot handbook opens in its own movable, closable window.","Das Buchsymbol oben rechts im Pet Atlas öffnet eine achtseitige Bildanleitung in einem beweglichen, schließbaren Fenster.","Книга справа вверху Атласа открывает восемь страниц со снимками в отдельном перемещаемом окне.","El libro arriba a la derecha del Atlas abre ocho páginas con capturas en una ventana independiente que puedes mover y cerrar.","Le livre en haut à droite de l’Atlas ouvre huit pages illustrées dans une fenêtre séparée, déplaçable et refermable.","O livro no canto superior direito do Atlas abre oito páginas com imagens numa janela separada que pode mover e fechar.","اضغط الكتاب أعلى يمين الأطلس لفتح دليل مصور من ثماني صفحات في نافذة مستقلة يمكن تحريكها وإغلاقها.","पेट एटलस के ऊपर दाएँ किताब दबाएँ। आठ पन्नों की चित्र गाइड अलग खिड़की में खुलती है जिसे हिला और बंद कर सकते हैं।","点击宠物图鉴右上角的书本图标，打开八页截图指南。独立窗口可移动和关闭。"],
        ["setupProgress"]=["Kurulum ekranı en az 6 saniye görünür. Çubuk tamamlanan işleri gösterir; işlem bitmeden dolmaz.","Setup remains visible for at least 6 seconds. The bar shows completed work and never fills before installation finishes.","Setup bleibt mindestens 6 Sekunden sichtbar. Der Balken zeigt erledigte Arbeit und wird erst nach Abschluss voll.","Экран установки виден минимум 6 секунд. Полоса показывает выполненные этапы и не заполнится до завершения.","La instalación se muestra al menos 6 segundos. La barra indica trabajo completado y no se llena antes de terminar.","L’installation reste visible au moins 6 secondes. La barre indique le travail effectué et ne se remplit qu’à la fin.","A instalação fica visível por pelo menos 6 segundos. A barra mostra o trabalho concluído e só enche ao terminar.","يبقى التثبيت ظاهراً 6 ثوانٍ على الأقل. الشريط يعرض العمل المنجز ولا يمتلئ قبل انتهاء التثبيت.","इंस्टॉलेशन स्क्रीन कम से कम 6 सेकंड दिखती है। बार पूरा हुआ काम दिखाता है और इंस्टॉलेशन खत्म होने से पहले नहीं भरता।","安装画面至少显示6秒。进度条显示已完成的工作，安装完成前不会填满。"],
        ["handbook"]=["Kısa rehber","Quick handbook","Kurzanleitung","Краткое руководство","Guía rápida","Guide rapide","Guia rápido","دليل سريع","त्वरित गाइड","快速指南"],
        ["guide"]=["Uygulama rehberi","App guide","App-Anleitung","Руководство","Guía de la aplicación","Guide de l’application","Guia do aplicativo","دليل التطبيق","ऐप गाइड","应用指南"],
        ["contact"]=["İletişim","Contact","Kontakt","Связаться","Contacto","Contact","Contato","تواصل","संपर्क","联系"],
        ["identityTitle"]=["Önce eşitle","Sync first","Zuerst synchronisieren","Сначала синхронизация","Sincroniza primero","Synchronisez d’abord","Sincronize primeiro","زامن أولاً","पहले सिंक करें","先同步"],
        ["identity"]=["Tracker açıkken karakter seçimine dönüp giriş yap. Kırmızı uyarı varsa sayaç yaklaşık olabilir; yeni collection gelince düzelir.","With the tracker open, relog through Character Select. A red warning means counts may be inaccurate; a new collection corrects them.","Mit offenem Tracker über die Charakterauswahl neu einloggen. Rot bedeutet mögliche Ungenauigkeit; eine neue Sammlung korrigiert sie.","Войдите через выбор персонажа при открытом трекере. Красное предупреждение: счёт может быть неточным; новая коллекция исправит его.","Vuelve a entrar desde selección de personaje con el tracker abierto. La alerta roja indica posibles errores; una nueva colección los corrige.","Reconnectez-vous via la sélection du personnage, tracker ouvert. Un avertissement rouge signale une incertitude ; la nouvelle collection la corrige.","Entre novamente pela seleção de personagem com o tracker aberto. O aviso vermelho indica possível imprecisão; a nova coleção corrige.","أعد الدخول من اختيار الشخصية والمتتبع مفتوح. التحذير الأحمر يعني احتمال عدم دقة العداد؛ مجموعة جديدة تصححه.","ट्रैकर खुला रखकर चरित्र चयन से दोबारा प्रवेश करें। लाल चेतावनी पर गिनती गलत हो सकती है; नया संग्रह उसे सुधारता है।","打开追踪器后从角色选择重新登录。红色警告表示计数可能不准确；新的收藏数据会校正。"],
        ["cardsTitle"]=["Kartlarını yönet","Manage your cards","Karten verwalten","Управляйте карточками","Gestiona tus tarjetas","Gérez vos cartes","Gerencie seus cartões","إدارة البطاقات","कार्ड व्यवस्थित करें","管理卡片"],
        ["cards"]=["Pin kartı sabit tutar. Pini kaldırmak kartı silmez; Delete/Clear kaldırır. Sol oklarla sırala. Pencere kart sayısına göre 1–7 kart arasında büyür ve küçülür; boşken 1 kartlık kalır.","Pin keeps a card. Unpin does not remove it; Delete/Clear does. Reorder with the left arrows. The window grows and shrinks to fit 1–7 cards; empty stays one card tall.","Pin hält die Karte. Entpinnen löscht sie nicht; Delete/Clear schon. Links sortieren. Das Fenster wächst und schrumpft passend für 1–7 Karten; leer bleibt es eine Karte hoch.","Закрепление сохраняет карточку. Открепление не удаляет; Delete/Clear удаляет. Порядок — стрелками слева. Окно растёт и уменьшается под 1–7 карточек; пустое остаётся высотой в одну карточку.","Fijar conserva la tarjeta. Desfijar no la elimina; Delete/Clear sí. Ordena con las flechas. La ventana crece y se reduce entre 1 y 7 tarjetas; vacía mantiene altura de una.","Épingler conserve la carte. Désépingler ne la supprime pas ; Delete/Clear oui. Triez avec les flèches. La fenêtre grandit et rétrécit pour 1 à 7 cartes ; vide, elle garde la hauteur d’une carte.","Fixar mantém o cartão. Desafixar não remove; Delete/Clear remove. Ordene pelas setas. A janela cresce e diminui entre 1 e 7 cartões; vazia, mantém altura de um.","التثبيت يبقي البطاقة. إلغاء التثبيت لا يحذفها؛ Delete/Clear يحذفها. رتّب بالأسهم. تكبر النافذة وتصغر لتناسب 1–7 بطاقات؛ فارغة تبقى بارتفاع بطاقة واحدة.","पिन कार्ड रखता है। अनपिन से नहीं हटता; Delete/Clear से हटता है। बाएँ तीर से क्रम बदलें। खिड़की 1–7 कार्ड के अनुसार बढ़ती और घटती है; खाली होने पर एक कार्ड जितनी रहती है।","固定可保留卡片。取消固定不会移除；Delete/Clear 才会移除。用左侧箭头排序。窗口随卡片数量在1至7张之间自动增减；无卡片时保留一张卡片的高度。"],
        ["atlasTitle"]=["Petleri bul","Find your pets","Pets finden","Найдите питомцев","Encuentra tus mascotas","Trouvez vos pets","Encontre seus pets","اعثر على الحيوانات","पेट खोजें","查找宠物"],
        ["atlas"]=["Dünya ikonuna bas. Peti seçerek bilgi kartını aç; Haritada göster ile bölge seç. Tüm farmlanabilir konumları ve yuvarlak portreleri tiklerden aç.","Click the globe. Select a pet for its info card; Show on map chooses a region. Enable all farmable locations and circular portraits with the checkboxes.","Globus anklicken. Pet wählen für Infos; Auf Karte zeigen wählt die Region. Farm-Orte und runde Porträts per Häkchen aktivieren.","Нажмите глобус. Выберите питомца для сведений; «На карте» выбирает регион. Фарм-места и портреты включаются флажками.","Pulsa el globo. Selecciona una mascota para ver su ficha; Mostrar en mapa elige región. Activa ubicaciones y retratos con las casillas.","Cliquez sur le globe. Choisissez un pet pour sa fiche ; Afficher sur la carte choisit la région. Activez les lieux et portraits via les cases.","Clique no globo. Selecione um pet para informações; Mostrar no mapa escolhe a região. Ative locais e retratos nas caixas.","اضغط الكرة الأرضية. اختر حيواناً لبطاقته؛ العرض على الخريطة يختار المنطقة. فعّل مواقع التجميع والصور من المربعات.","ग्लोब दबाएँ। जानकारी के लिए पेट चुनें; मानचित्र विकल्प से क्षेत्र चुनें। चेकबॉक्स से सभी फ़ार्म स्थान और गोल चित्र दिखाएँ।","点击地球图标。选择宠物查看信息卡；在地图显示可选择区域。勾选显示全部可收集位置和圆形头像。"],
        ["keysTitle"]=["Gizle veya küçült","Hide or compact","Ausblenden oder verkleinern","Скрыть или свернуть","Oculta o reduce","Masquer ou réduire","Oculte ou reduza","إخفاء أو تصغير","छिपाएँ या छोटा करें","隐藏或缩小"],
        ["keys"]=["Ctrl+P gizler/gösterir. Ctrl+U küçültür/büyütür. Ayarlardan değiştir. Masaüstü kısayolu açık tracker’ı geri getirir.","Ctrl+P hides/restores. Ctrl+U compacts/expands. Change them in Settings. The desktop shortcut restores the running tracker.","Ctrl+P blendet aus/ein. Ctrl+U verkleinert/vergrößert. In Einstellungen ändern. Desktop-Verknüpfung holt den Tracker zurück.","Ctrl+P скрывает/показывает. Ctrl+U сворачивает/разворачивает. Меняйте в настройках. Ярлык возвращает открытый трекер.","Ctrl+P oculta/restaura. Ctrl+U reduce/expande. Cámbialos en Ajustes. El acceso directo restaura el tracker abierto.","Ctrl+P masque/restaure. Ctrl+U réduit/agrandit. Modifiez-les dans les paramètres. Le raccourci restaure le tracker ouvert.","Ctrl+P oculta/restaura. Ctrl+U reduz/expande. Altere nas Configurações. O atalho restaura o tracker aberto.","Ctrl+P يخفي/يستعيد. Ctrl+U يصغّر/يكبّر. غيّرها في الإعدادات. اختصار سطح المكتب يستعيد المتتبع المفتوح.","Ctrl+P छिपाता/दिखाता है। Ctrl+U छोटा/बड़ा करता है। सेटिंग में बदलें। डेस्कटॉप शॉर्टकट खुले ट्रैकर को वापस लाता है।","Ctrl+P隐藏/恢复。Ctrl+U缩小/展开。可在设置中修改。桌面快捷方式可恢复运行中的追踪器。"],
        ["riftTitle"]=["Rift hatırlatıcısı","Rift reminders","Rift-Erinnerungen","Напоминания о разломе","Avisos de Rift","Rappels de Rift","Lembretes de Rift","تذكير الصدع","रिफ्ट अनुस्मारक","裂隙提醒"],
        ["rift"]=["Uyarılar varsayılan olarak açıktır; Spacetime Rift menüsünden kapatabilir ve süreyi değiştirebilirsin. Varsayılan 5 dakika önce ve açılışta bildirir. Saatler topluluk takvimidir; canlı spawn doğrulaması değildir.","Alerts start enabled; disable them or change the lead time in Spacetime Rift. Default: 5 minutes before and at opening. Times follow a community schedule, not verified live spawns.","Standardmäßig aktiv; in Spacetime Rift deaktivieren oder Vorlauf ändern. Standard: 5 Minuten vorher und beim Öffnen. Community-Zeitplan, keine Live-Spawn-Bestätigung.","По умолчанию включено; отключение и время — в Spacetime Rift. По умолчанию: за 5 минут и при открытии. Расписание сообщества, не подтверждение живого спавна.","Avisos activados por defecto; desactívalos o ajusta el tiempo en Spacetime Rift: 5 minutos antes y al abrir. Horario comunitario; no confirma apariciones en vivo.","Alertes actives par défaut ; désactivez-les ou réglez le délai dans Spacetime Rift : 5 minutes avant et à l’ouverture. Calendrier communautaire, pas de confirmation en direct.","Alertas ativos por padrão; desative ou ajuste em Spacetime Rift: 5 minutos antes e na abertura. Agenda da comunidade, sem confirmação de spawn ao vivo.","التنبيهات مفعلة افتراضياً؛ أوقفها أو عدّل الوقت في Spacetime Rift: قبل 5 دقائق وعند الفتح. جدول مجتمعي وليس تأكيد ظهور مباشر.","अलर्ट डिफ़ॉल्ट चालू हैं; Spacetime Rift में बंद करें या समय बदलें: 5 मिनट पहले और खुलने पर। समय सामुदायिक तालिका है, लाइव स्पॉन की पुष्टि नहीं।","提醒默认开启，可在Spacetime Rift中关闭或调整提前时间：默认提前5分钟及开放时通知。采用社区时间表，并非实时生成确认。"],
        ["portraits"]=["Haritada Portre Olarak Göster","Show Portraits on Map","Porträts auf Karte anzeigen","Показать портреты на карте","Mostrar retratos en el mapa","Afficher les portraits sur la carte","Mostrar retratos no mapa","عرض الصور على الخريطة","मानचित्र पर चित्र दिखाएँ","在地图上显示头像"]
    };
    public static string Get(string language,string key)=>Texts[key][Array.FindIndex(UiText.Languages,l=>l.Code==language) is var i&&i>=0?i:1];
    public static bool Complete=>Texts.Values.All(v=>v.Length==10&&v.All(s=>!string.IsNullOrWhiteSpace(s)));
}

internal static class AppLinks
{
    public const string Guide="https://keytdev.com/pettracker/";
    public const string Email="support@keytdev.com";
    public static void Open(IWin32Window owner,string url,string language)
    {
        try{using var process=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(url){UseShellExecute=true});}
        catch(Exception ex)when(ex is System.ComponentModel.Win32Exception or InvalidOperationException)
        {MessageBox.Show(owner,UiText.Get(language,"browserFailed"),"Pet Tracker",MessageBoxButtons.OK,MessageBoxIcon.Information);}
    }
}
